{"results": [{"id": "hp_doc_0545ed760fd9529adf4863b9fd68031db285667708afbbc748ab4f529ffa0655", "title": "Moscow Hemp Fest", "text": "The Moscow Hemp Fest (sometimes Moscow Hempfest) is an annual cannabis event held in Moscow, Idaho, in the United States. It began in 1996 for the University of Idaho's Mom's Weekend.", "score": 31.9938}, {"id": "hp_doc_dd949ff692db45f6349a50e5ec3f65d18b70a295042229c1b01625071533efc6", "title": "Santa Cruz Hemp Allstars", "text": "The Santa Cruz Hemp Allstars are a super-jam group put together by Poco Marshall, featuring members of Sound Tribe Sector 9, Estradasphere, , The Disco Biscuits, The Slip, The Living Daylights, and DJ Logic. The first show was held at Palookaville in Santa Cruz, California on April 20, 2001 as a Santa Cruz Hemp Fest afterparty. The group plays totally unrehearsed improvised jam sessions. There have only been a total of seven appearances ever by the Santa Cruz Hemp Allstars. Their last show was completely sold out.", "score": 17.4274}, {"id": "hp_doc_a4782cf63b31ced10e9bca90c02c4378b13f760a013d0271f97c102cd9fd046a", "title": "Salem Hempfest", "text": "Salem Hempfest, or Salem Hemp Fest, is a cannabis festival in Salem, Oregon, in the United States. The inaugural event was held in Riverfront Park in 2015.", "score": 17.3616}], "remaining_searches": 2}
